"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9161],{15495:e=>{e.exports=JSON.parse('{"functions":[{"name":"fetch","desc":"Sends one shop\'s current stock to a single player as a `SHOP_REFRESH`\\ndispatch. Silently no-ops for an unknown shop.","params":[{"name":"player","desc":"recipient","lua_type":"Player"},{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":141,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"generateStock","desc":"Computes the stock every shop should be holding right now and writes it into\\nthe shop replicas.\\n\\nFor each item it finds the most recent restock time that should have\\noccurred (`floor(now / restockInterval) * restockInterval`) and refills to\\n`maxStockQuantity` only when that moment lies inside the current global\\nrestock window; otherwise the existing quantity is carried forward. Replicas\\nare only written when something actually changed, so an idle cycle costs no\\nreplication.","params":[],"returns":[{"desc":"shopType -> itemId -> quantity","lua_type":"{ [string]: { [string]: number } }"}],"function_type":"static","source":{"line":174,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"applyStock","desc":"Writes a previously computed stock table back onto the shop replicas,\\nclamping quantities at zero. Unknown shops and unknown items are skipped,\\nand replicas are only touched when a quantity actually changed.\\n\\nUsed by [ShopService.initializeStock] to restore in-memory stock rather than\\nregenerating it.","params":[{"name":"stockByShop","desc":"shopType -> itemId -> quantity","lua_type":"{ [string]: { [string]: number } }"}],"returns":[],"function_type":"static","source":{"line":252,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"getCurrentStock","desc":"Returns the in-memory stock snapshot, or nil when none has been taken yet\\nthis server lifetime.","params":[],"returns":[{"desc":"","lua_type":"{ [string]: { [string]: number } }?"}],"function_type":"static","source":{"line":287,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"getTimeUntilRestock","desc":"Returns the seconds remaining until the next global restock window, or 0\\nwhen a window is open right now and this server has not yet processed it.\\n\\n\\"Open right now\\" means within one second of a\\n`ShopData.STOCK_REFRESH_INTERVAL` boundary and on a cycle ordinal greater\\nthan `_lastRestockCycle` \u2014 the ordinal comparison is what prevents the same\\ncycle firing repeatedly during that one-second window.","params":[],"returns":[{"desc":"seconds until restock, 0 when due","lua_type":"number"}],"function_type":"static","source":{"line":309,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"saveStockToLocalStorage","desc":"Stores a stock snapshot in the module-level `LocalStorage` table. In-memory\\nonly \u2014 nothing is written to a DataStore, so this does not survive a server\\nrestart.","params":[{"name":"stockByShop","desc":"shopType -> itemId -> quantity","lua_type":"{ [string]: { [string]: number } }"}],"returns":[],"function_type":"static","source":{"line":342,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"saveRestockTime","desc":"Stamps the current server time onto every shop replica\'s `lastRestockTime`\\nand into `LocalStorage`. The replica field is retained for client\\ncompatibility; the scheduling itself is derived from the clock rather than\\nfrom this value.","params":[],"returns":[],"function_type":"static","source":{"line":357,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"persistStockAndTime","desc":"Unified stock persistence: snapshots the stock and stamps the restock time\\nin one call. Both writes are in-memory.","params":[{"name":"stock","desc":"shopType -> itemId -> quantity","lua_type":"{ [string]: { [string]: number } }"}],"returns":[],"function_type":"static","private":true,"source":{"line":378,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"performRestock","desc":"Runs one restock cycle: regenerates stock, advances `_lastRestockCycle` to\\nthe current cycle ordinal so this window cannot fire again, snapshots the\\nresult, and broadcasts a single \\"The shops have restocked!\\" toast to\\neveryone if any shop ended up holding stock.","params":[],"returns":[],"function_type":"static","source":{"line":392,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"getShopStock","desc":"Returns a shop\'s live `StockItem` map straight off its replica (carrying both\\n`quantity` and `maxStockQuantity`), or nil for an unknown shop.\\n\\nThe returned table is the replica\'s own data \u2014 mutating it must be followed\\nby a `replica:Set(\\"items\\", \u2026)` to replicate.","params":[{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"}],"returns":[{"desc":"","lua_type":"{ [string]: ShopData.StockItem }?"}],"function_type":"static","source":{"line":440,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"validateStockOperation","desc":"Consolidated stock validation for the decrement paths. Resolves the shop and\\nits stock entry, returning nil unless the shop exists, stocks that item, and\\ncurrently holds a quantity above zero.","params":[{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"},{"name":"itemId","desc":"item to validate","lua_type":"string"}],"returns":[{"desc":"the shop, when valid","lua_type":"ShopData?"},{"desc":"the stock entry, when valid","lua_type":"ShopData.StockItem?"}],"function_type":"static","private":true,"source":{"line":460,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"persistStockChange","desc":"Mirrors a single item\'s new quantity into the in-memory stock snapshot, so a\\nlater [ShopService.applyStock] restores post-purchase quantities rather than\\nthe last generated ones. No-ops when no snapshot exists or the item is not\\nin it.","params":[{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"},{"name":"itemId","desc":"item that changed","lua_type":"string"},{"name":"newQuantity","desc":"quantity to record","lua_type":"number"}],"returns":[],"function_type":"static","private":true,"source":{"line":495,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"decrementStock","desc":"Consumes stock for a purchase, replicating the change and mirroring it into\\nthe in-memory snapshot.\\n\\n:::caution Ignores `quantity`\\n`quantity` is only used for the affordability check \u2014 the body always\\ndecrements by exactly 1 regardless of how many were bought. Multi-buys\\ntherefore under-consume stock. Use\\n[ShopService.subtractQuantityFromItem] when the amount must be honoured.\\n:::","params":[{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"},{"name":"itemId","desc":"item being bought","lua_type":"string"},{"name":"quantity","desc":"amount requested; checked but not applied","lua_type":"number"}],"returns":[{"desc":"false when the shop, item or available stock is insufficient","lua_type":"boolean"}],"function_type":"static","source":{"line":522,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"giveItemToPlayer","desc":"Grants an item into the player\'s inventory through\\n[InventoryService.addQuantityToItemId], which handles stacking and slot\\nallocation.","params":[{"name":"player","desc":"recipient","lua_type":"Player"},{"name":"itemId","desc":"item to grant","lua_type":"string"},{"name":"quantity","desc":"amount, defaults to 1","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":554,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"subtractQuantityFromItem","desc":"Removes an arbitrary amount of stock from a shop item, clamped at zero, then\\nreplicates and snapshots the change. Unlike [ShopService.decrementStock],\\nthis honours the amount passed.","params":[{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"},{"name":"itemId","desc":"item to reduce","lua_type":"string"},{"name":"amount","desc":"how much stock to remove","lua_type":"number"}],"returns":[{"desc":"false when the shop or item is unknown, or stock is already zero","lua_type":"boolean"}],"function_type":"static","source":{"line":577,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"checkOwnershipLimit","desc":"Returns whether the player can purchase the item and the number of items\\nthey own.\\n\\nItems with no `ownershipLimit` (or a limit of 0) are unlimited and always\\npass. Counting differs by item type:\\n\\n- **Skin** \u2014 an [ItemRecord] in `profile.inventory` like everything else,\\n  but treated as a boolean unlock via [CosmeticService.ownsSkin].\\n- **Prop** \u2014 inventory quantity plus any props the player has already\\n  placed in the world. That second term currently always reads zero: the\\n  `BaseService` dependency is a local stub pending the Base system port.\\n- everything else \u2014 the summed quantity of matching inventory records.","params":[{"name":"player","desc":"prospective buyer","lua_type":"Player"},{"name":"itemId","desc":"item to check","lua_type":"string"}],"returns":[{"desc":"whether a purchase is permitted","lua_type":"boolean"},{"desc":"how many the player already owns","lua_type":"number"}],"function_type":"static","source":{"line":618,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"purchase","desc":"Buys a **non-stocked** item with soft currency.\\n\\nRejects anything hidden, unpriced, or carrying `stockData` \u2014 stocked items\\ngo through [ShopService.purchaseStock] instead. Checks the ownership limit\\nand the balance, debits via [CurrencyService.take], logs a `Sink` resource\\nevent, then grants one copy.\\n\\nNote that `quantity` is asserted positive but is otherwise unused: exactly\\none item is charged for and granted.","params":[{"name":"player","desc":"buyer","lua_type":"Player"},{"name":"itemId","desc":"item to buy","lua_type":"string"},{"name":"quantity","desc":"asserted positive; not otherwise honoured","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":679,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"purchaseStock","desc":"Buys an item from a specific shop, honouring stock when scarcity is enabled.\\n\\nThe order of operations is: validate the item, check the ownership limit,\\nverify the balance, **debit the currency**, then attempt the stock\\ndecrement. Because payment happens before the stock check, a failed\\ndecrement is compensated by an explicit refund (logged as a `Refund`\\nresource event) rather than avoided.\\n\\nThe stock decrement only runs when both hold: `FeatureFlags.ScarcityShop`\\nis on and the item declares `stockData`. With the flag off (the default)\\nthe branch is skipped entirely and stock is effectively infinite.\\n\\nSkins are handled by [CosmeticService.markPurchased] instead of\\n[ShopService.giveItemToPlayer]: they\'re recorded as a boolean unlock, not\\na stackable quantity, and are auto-equipped and applied to both the\\ncharacter and the held item.","params":[{"name":"player","desc":"buyer","lua_type":"Player"},{"name":"shopType","desc":"what shop the player is buying from","lua_type":"string"},{"name":"itemId","desc":"item to buy","lua_type":"string"},{"name":"quantity","desc":"amount, defaults to 1; priced per unit","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":762,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"setupShops","desc":"Creates one shop replica per non-custom entry in `ShopData.SHOPS`. Custom\\nshops (skins, market) ship their own component and do not participate in the\\nscarcity stock system, so they are skipped.","params":[],"returns":[{"desc":"the union of item types across all created shops","lua_type":"{ string }"}],"function_type":"static","private":true,"source":{"line":894,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"populateShopItems","desc":"Seeds every shop replica with a zero-quantity entry for each stockable item\\nwhose type that shop supports, so the item exists in the replica before the\\nfirst restock fills it.","params":[{"name":"supportedItemTypes","desc":"item types across all shops, from setupShops","lua_type":"{ string }"}],"returns":[],"function_type":"static","private":true,"source":{"line":937,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"initializeStock","desc":"Restores the in-memory stock snapshot if one exists, otherwise runs a full\\n[ShopService.performRestock] to generate stock from scratch.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":962,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"startRestockLoop","desc":"Spawns the restock poller. It sleeps until the next window, but never for\\nmore than one second at a time, so the narrow one-second window in\\n[ShopService.getTimeUntilRestock] cannot be slept through.\\n\\nOnly started when `FeatureFlags.ScarcityShop` is on.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":983,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"clearLocalStorage","desc":"Clears the in-memory stock snapshot and restock timestamp. Useful for\\ntesting \u2014 the next [ShopService.initializeStock] will regenerate stock from\\nscratch rather than restoring it.","params":[],"returns":[],"function_type":"static","source":{"line":1007,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"getRestockInfo","desc":"Builds a debug snapshot of restock timing: the global refresh interval and\\nthe time left on it, plus per-shop, per-item restock interval, time\\nremaining and current quantity. `modulus` on each entry is the elapsed time\\nwithin that interval, which is what the scheduling comparisons key off.\\n\\nRead-only \u2014 computing this does not advance any cycle.","params":[],"returns":[{"desc":"`{ globalRefresh = {...}, shops = { [shopType] = { [itemId] = {...} } } }`","lua_type":"table"}],"function_type":"static","source":{"line":1025,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"manualRestock","desc":"Force-restocks a single shop, used at boot so items are available\\nimmediately rather than after the first scheduled window.\\n\\nDiffers from the scheduled path in what it guarantees: items of\\n`INITIAL_STOCK_RARITY` (\\"Common\\") and all props are filled to\\n`maxStockQuantity` unconditionally, while rarer items only restock if their\\nown interval boundary is within the last second \u2014 and even then they refill\\nto 0 rather than their max, so rare stock is never seeded at boot.\\n\\nAdvances `_lastRestockCycle` on success so the scheduled loop does not\\nimmediately repeat the work, and broadcasts the restock toast.","params":[{"name":"shopType","desc":"key in `ShopData.SHOPS`","lua_type":"string"}],"returns":[{"desc":"whether anything actually restocked","lua_type":"boolean"}],"function_type":"static","source":{"line":1106,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"giveItem","desc":"Legacy grant path: builds an [ItemRecord] by hand and appends it to the\\nprofile via the `inventory.++` path operator, then notifies the client with\\n`ITEM_SHOP_ITEM_ADD`.\\n\\nUnlike [ShopService.giveItemToPlayer] this bypasses [InventoryService]\\nentirely, so it performs no stacking against existing records and always\\nplaces the item in the bag. Used by the redeem-code and\\n[ShopService.purchaseItem] flows.","params":[{"name":"player","desc":"recipient","lua_type":"Player"},{"name":"itemId","desc":"item to grant","lua_type":"string"},{"name":"showInventory","desc":"whether the client should pop the inventory open","lua_type":"boolean?"},{"name":"quantity","desc":"amount, defaults to 1","lua_type":"number?"}],"returns":[{"desc":"the record created","lua_type":"Types.ItemRecord?"}],"function_type":"static","private":true,"source":{"line":1205,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"isCodeRedeemed","desc":"Returns whether this player has already redeemed a code.\\n\\nChecks the in-memory `redemptionCache` first, then falls back to the\\n`redeemed_codes` DataStore under the key `<userId>-<code>`, retried up to 3\\ntimes. A successful lookup is cached so repeat attempts do not hit the\\ndatastore again. Always false in Studio, where the datastore is not created.","params":[{"name":"player","desc":"redeemer","lua_type":"Player"},{"name":"code","desc":"code to check","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","private":true,"source":{"line":1254,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"redeemCode","desc":"Redeems a promo code from `Data/ShopCodes` and grants its item.\\n\\nThe code is upper-cased before lookup. Redemption is rejected when the code\\nis unknown, its item does not exist, it requires Premium the player lacks,\\nthe server is Studio (codes are disabled there), or it has already been\\nredeemed. Otherwise the redemption is written to the `redeemed_codes`\\nDataStore **first** \u2014 the grant only happens if that write succeeds, so a\\ndatastore failure cannot produce a free duplicate.\\n\\nReplies with a `UI_TOAST` on success or `ITEM_SHOP_ERROR` on any rejection.","params":[{"name":"player","desc":"redeemer","lua_type":"Player"},{"name":"payload","desc":"carries the entered code","lua_type":"ShopTypes.ShopRedeemCodePayload"}],"returns":[],"function_type":"static","source":{"line":1305,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"purchaseItem","desc":"Legacy catalogue purchase path, driven from the shop UI.\\n\\nChecks the ownership limit (reporting `owned/limit` back to the player when\\nexceeded), then debits coins through [CurrencyService.take], which refuses a\\npurchase the balance can\'t cover. Unlike the other purchase paths it does not\\nlog a resource analytics event. Items with no `purchasePrice` are granted free.","params":[{"name":"player","desc":"buyer","lua_type":"Player"},{"name":"payload","desc":"carries the item id","lua_type":"ShopTypes.ShopPurchasePayload"}],"returns":[],"function_type":"static","source":{"line":1372,"path":"src/Server/Features/Shop/ShopService.luau"}},{"name":"init","desc":"Boots the service: binds the `Handlers` folder, and registers the `item`\\ndeveloper-product callback so a purchased item is granted through\\n[InventoryService] once the receipt is processed.\\n\\nThe shop stock machinery \u2014 replica setup, item population, initial stock,\\nthe per-shop boot restock and the restock loop \u2014 is entirely behind\\n`FeatureFlags.ScarcityShop`, which is off by default. With it off, no shop\\nreplicas exist at all and clients see no stock data.","params":[],"returns":[],"function_type":"static","source":{"line":1450,"path":"src/Server/Features/Shop/ShopService.luau"}}],"properties":[],"types":[],"name":"ShopService","desc":"Handles shop management, including stock for multiple shop types.\\n\\nOne [Replica] is created per non-custom shop defined in `ShopData.SHOPS`,\\neach holding a `{ [itemId]: StockItem }` map that is the single source of\\ntruth clients read stock from. Shops marked `custom` (skins, player market)\\nship their own component and are skipped entirely \u2014 they do not participate\\nin the stock system.\\n\\n## Restock scheduling\\n\\nRestocking is derived from wall-clock time rather than tracked per item.\\nTwo intervals interact:\\n\\n- `ShopData.STOCK_REFRESH_INTERVAL` \u2014 the global cycle. `_lastRestockCycle`\\n  records the cycle ordinal already processed, which is what stops a cycle\\n  from firing twice.\\n- `item.stockData.restockInterval` \u2014 per item. An item\'s most recent due\\n  restock is `floor(now / interval) * interval`; it refills to\\n  `maxStockQuantity` only when that timestamp falls inside the current\\n  global window, otherwise it keeps its quantity.\\n\\n[ShopService.startRestockLoop] polls [ShopService.getTimeUntilRestock] at\\nmost once a second and calls [ShopService.performRestock] when the window\\nopens.\\n\\n:::caution Stock is not persisted\\nDespite the `save*` naming, `LocalStorage` is a plain in-memory table on the\\nserver \u2014 [ShopService.saveStockToLocalStorage] and\\n[ShopService.saveRestockTime] write no DataStore, so stock and the restock\\nclock reset on every server start. The only DataStore this module touches is\\n`redeemed_codes`, used by the redeem-code flow.\\n:::\\n\\n## Feature gate\\n\\n`FeatureFlags.ScarcityShop` is **off** by default. When off,\\n[ShopService.init] never builds the shop replicas, never populates stock and\\nnever starts the restock loop, and [ShopService.purchaseStock] skips its\\nstock-decrement step entirely \u2014 so stock is effectively infinite and\\npurchases are limited only by currency and ownership limits. Handlers,\\nredeem codes and the marketplace item callback all remain active.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":50,"path":"src/Server/Features/Shop/ShopService.luau"}}')}}]);